import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BN3Eol-0.js";const k=JSON.parse('{"title":"Rolling back a bad prod deploy","description":"","frontmatter":{},"headers":[],"relativePath":"ops/rollback.md","filePath":"ops/rollback.md"}'),o={name:"ops/rollback.md"};function d(l,e,r,n,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="rolling-back-a-bad-prod-deploy" tabindex="-1">Rolling back a bad prod deploy <a class="header-anchor" href="#rolling-back-a-bad-prod-deploy" aria-label="Permalink to &quot;Rolling back a bad prod deploy&quot;">​</a></h1><p><strong>Decision (2026-11-09):</strong> the rollback for a bad prod deploy is to <strong>redeploy the previous working release</strong>, then <strong>fix forward on <code>main</code></strong>. No revert-and-wait cycle during an incident.</p><p><strong>Status:</strong> this runbook describes <code>Deploy to prod VPS (orrery)</code> with the <code>release_tag</code> input from <code>docs/wip/2026-11-09-deploy-release-tag.patch</code>. Until that patch is applied to <code>.github/workflows/deploy-prod.yml</code>, the input does not exist and the older procedure in <a href="./deploy-prod-vps">deploy-prod-vps.md</a> (&quot;Rollback&quot;) is the only one.</p><h2 id="when-to-roll-back" tabindex="-1">When to roll back <a class="header-anchor" href="#when-to-roll-back" aria-label="Permalink to &quot;When to roll back&quot;">​</a></h2><p>Roll back when a deploy left the public site or a backend broken and the cause is not a one-line fix you can ship in minutes: the <code>validate</code> job is red on something users hit, routes 500/blank, lab-api or mcp crash-looping, the wrong data served. Do not roll back for a problem the previous release also had.</p><h2 id="roll-back" tabindex="-1">Roll back <a class="header-anchor" href="#roll-back" aria-label="Permalink to &quot;Roll back&quot;">​</a></h2><p>From any checkout with <code>gh</code> authenticated, dispatch from <code>main</code> (the deploy job only runs on <code>main</code>) and name the last good release tag:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Deploy to prod VPS (orrery)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release_tag=v0.9.7</span></span></code></pre></div><p>What the tag drives (blank <code>release_tag</code> = today&#39;s behaviour, main HEAD):</p><table tabindex="0"><thead><tr><th>Part</th><th>Comes from with <code>release_tag</code></th></tr></thead><tbody><tr><td>Static bundle (<code>build/</code>, <code>static/data</code> seed)</td><td>built in the job from the tag&#39;s commit</td></tr><tr><td>Server files (compose, Caddy drop-ins, <code>ops/</code>)</td><td>VPS <code>git fetch &lt;sha&gt;</code> + <code>git reset --hard &lt;sha&gt;</code></td></tr><tr><td><code>orrery-mcp</code>, <code>orrery-lab-api</code>, <code>orrery-pipeline-runner</code></td><td>GHCR <code>sha-&lt;7&gt;</code> of the tag&#39;s commit</td></tr><tr><td><code>ORRERY_RELEASE</code> / <code>PUBLIC_SENTRY_RELEASE</code> / source-map artifact name</td><td>the tag&#39;s commit (<code>sha-&lt;7&gt;</code> / <code>gha-&lt;8&gt;</code>)</td></tr><tr><td>Post-deploy <code>validate</code> job</td><td>checks out the tag&#39;s commit, so the release&#39;s own validator judges it</td></tr></tbody></table><p>Refusals, all before anything is built or touched: tag not matching <code>vX.Y.Z[-pre]</code>, tag does not exist, tag&#39;s commit is not an ancestor of <code>main</code>, the commit&#39;s three <code>sha-&lt;7&gt;</code> images are not all on GHCR, or <code>override_image_sha</code> is also set (the two inputs are exclusive).</p><p>Not rolled back (a deploy never touches them): <code>lab-api-state</code> (keys, allowlist), the on-box <code>static/data</code> overlay (the seed is additive, so files newer than the release stay), and anything a migration changed outside the repo.</p><h2 id="watch-it" tabindex="-1">Watch it <a class="header-anchor" href="#watch-it" aria-label="Permalink to &quot;Watch it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Deploy to prod VPS (orrery)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exit-status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # approve the prod environment gate if asked</span></span></code></pre></div><p>The &quot;Resolve release tag (rollback)&quot; step prints <code>&lt;tag&gt; -&gt; &lt;sha&gt;; compare main...&lt;sha&gt;: identical|behind</code> and the notice <code>ROLLBACK: deploying &lt;tag&gt; (&lt;sha7&gt;), not main HEAD</code>. If you do not see that notice, the input was blank and you deployed main HEAD.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><ol><li><p>The run&#39;s <code>validate</code> job is green (it runs <code>npm run validate-prod</code> against the public URL, using the tag&#39;s own validator).</p></li><li><p>The live site reports the release. <code>PUBLIC_SENTRY_RELEASE</code> is <code>gha-</code> plus the first 8 chars of the deployed commit:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.orrerylearn.com/_app/env.js</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;PUBLIC_SENTRY_RELEASE:&quot;[^&quot;]*&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rev-parse</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short=8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.9.7</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # must match the part after gha-</span></span></code></pre></div><p>The footer version chip shows <code>package.json</code> version of the same commit.</p></li><li><p>On the box, <code>grep ORRERY_RELEASE /srv/orrery/.env</code> is <code>sha-&lt;7&gt;</code> of the tag&#39;s commit and <code>git -C /srv/orrery rev-parse --short HEAD</code> matches.</p></li><li><p>The separate <code>Validate prod</code> workflow also fires on deploy completion but runs <strong>main&#39;s</strong> validator (checks out main HEAD). On a rollback a red result there can be main-only assertions failing against the older release; the deploy&#39;s own <code>validate</code> job is the gate.</p></li></ol><h2 id="then-fix-forward" tabindex="-1">Then fix forward <a class="header-anchor" href="#then-fix-forward" aria-label="Permalink to &quot;Then fix forward&quot;">​</a></h2><p>Fix the bug on <code>main</code> as usual (repro first), let CI and docker-e2e publish the new <code>sha-&lt;7&gt;</code> images, and deploy normally (blank <code>release_tag</code>). Until then the prod VPS checkout sits on the tag&#39;s commit, not on <code>origin/main</code>; the next normal deploy puts it back.</p><h2 id="static-bundle-and-chunk-caveat" tabindex="-1">Static bundle and chunk caveat <a class="header-anchor" href="#static-bundle-and-chunk-caveat" aria-label="Permalink to &quot;Static bundle and chunk caveat&quot;">​</a></h2><p>The bundle is content-hashed chunks plus HTML that names them. A redeploy rsyncs the whole <code>build/</code> with <code>--delete</code>, so HTML and chunks always come from the same release; a rollback does not leave the server serving HTML that names a deleted chunk. Clients that cached HTML or chunks from the bad release (browser cache, the PWA service worker) are not verified here; check a hard reload after rolling back.</p>`,21)])])}const g=a(o,[["render",d]]);export{k as __pageData,g as default};
